/**
 * 20: writes src/domains/news/entries.ts, which imports every file of
 * content/changelog (a test checks it is up to date). Run after adding an
 * entry: npx tsx scripts/changelog-index.ts
 */
import { readdirSync, writeFileSync } from "node:fs";

export function changelogFiles() {
  return readdirSync("content/changelog")
    .filter((f) => /^\d{4}-\d{2}-\d{2}-[a-z0-9-]+\.json$/.test(f))
    .sort();
}
export function indexSource(files: string[]) {
  const names = files.map((_, i) => `e${i}`);
  return [
    "// Generated by scripts/changelog-index.ts from content/changelog: do not edit by hand.",
    ...files.map((f, i) => `import ${names[i]} from "../../../content/changelog/${f}";`),
    "",
    "export const rawEntries: { id: string; data: unknown }[] = [",
    ...files.map((f, i) => `  { id: ${JSON.stringify(f.replace(/\.json$/, ""))}, data: ${names[i]} },`),
    "];",
    "",
  ].join("\n");
}
if (process.argv[1]?.endsWith("changelog-index.ts")) writeFileSync("src/domains/news/entries.ts", indexSource(changelogFiles()));
